CREATE OR REPLACE FUNCTION public.revoke_signature(p_signature_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.document_signatures%ROWTYPE;
  v_caller uuid := auth.uid();
  v_is_admin boolean := false;
  v_is_org_member boolean := false;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'auth required';
  END IF;

  SELECT * INTO v_row FROM public.document_signatures WHERE id = p_signature_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'signature not found';
  END IF;

  -- Уже финальный статус — нечего отзывать
  IF v_row.status IN ('signed', 'rejected', 'revoked') THEN
    RAISE EXCEPTION 'cannot revoke signature in status: %', v_row.status;
  END IF;

  -- Проверка прав: либо отправитель, либо член организации с правом на documents,
  -- либо админ платформы
  v_is_admin := public.has_admin_role(v_caller);
  v_is_org_member := (v_row.sender_user_id = v_caller)
    OR public.has_org_staff_permission(v_caller, v_row.organization_id, 'documents'::text);

  IF NOT (v_is_admin OR v_is_org_member) THEN
    RAISE EXCEPTION 'permission denied';
  END IF;

  UPDATE public.document_signatures
  SET status = 'revoked',
      rejected_at = now(),
      rejection_reason = COALESCE(NULLIF(trim(p_reason), ''), 'Отозвано отправителем'),
      updated_at = now()
  WHERE id = p_signature_id;

  RETURN jsonb_build_object('ok', true, 'signature_id', p_signature_id, 'revoked_at', now());
END;
$function$

CREATE OR REPLACE FUNCTION public.sender_countersign(p_signature_id uuid, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid; v_sig RECORD;
BEGIN
  v_user := auth.uid();
  IF v_user IS NULL THEN RAISE EXCEPTION 'Auth required'; END IF;
  SELECT * INTO v_sig FROM document_signatures WHERE id = p_signature_id;
  IF v_sig IS NULL THEN RAISE EXCEPTION 'Not found'; END IF;
  IF v_user <> v_sig.sender_user_id THEN RAISE EXCEPTION 'Only sender can countersign'; END IF;
  IF v_sig.status <> 'signed' THEN RAISE EXCEPTION 'Recipient must sign first'; END IF;
  UPDATE document_signatures
  SET sender_signed_at = now(), sender_signed_ip = p_ip,
      sender_signed_user_agent = p_user_agent, updated_at = now()
  WHERE id = p_signature_id;
END; $function$
